const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { spawnSync } = require('node:child_process');

const root = path.join(__dirname, '..');
const read = file => fs.readFileSync(path.join(root, file), 'utf8');

test('generated browser bundle stays identical to the reviewed question packs', () => {
  const result = spawnSync(process.execPath, ['scripts/build_question_pack_bundle.cjs', '--check'], { cwd: root, encoding: 'utf8' });
  assert.equal(result.status, 0, result.stderr || result.stdout);
});

test('catalog bundle assembles reviewed packs without requesting extra scripts', () => {
  const writes = [];
  const context = { window: {}, document: { readyState: 'loading', write(value) { writes.push(value); } } };
  vm.createContext(context);
  vm.runInContext(read('public/catalog-runtime.js'), context);
  assert.equal(context.window.ManjingoContent.questions.length, 607);
  assert.deepEqual(writes, []);
});

test('browser bundle exposes every reviewed pack before the catalog assembles questions', () => {
  const context = { window: {}, Map, Set, Array, Object, Number, String, Math, RegExp };
  vm.createContext(context);
  vm.runInContext(read('public/question-packs-core.js'), context);
  vm.runInContext(read('public/content-catalog.js'), context);
  assert.equal(context.window.ManjingoContent.questions.length, 607);
  assert.equal(context.window.ManjingoContent.passageSets.length, 6);
  assert.ok(context.window.ManjingoContent.questions.some(question => question.id === 'fq022'));
  assert.ok(context.window.ManjingoContent.questions.some(question => question.id === 'rq016'));
  assert.ok(context.window.ManjingoContent.questions.some(question => question.id === 'toq022'));
  assert.ok(context.window.ManjingoContent.questions.some(question => question.id === 'psq018'));
});

test('production smoke waits for and verifies the deployed bundle', () => {
  const workflow = read('.github/workflows/pages-production-smoke.yml');
  const smoke = read('scripts/smoke_pages_api.mjs');
  assert.match(workflow, /question-packs-core\.js/);
  assert.match(workflow, /Generated by scripts\/build_question_pack_bundle\.cjs/);
  assert.match(smoke, /deployed core question catalog uses one verified pack bundle/);
  assert.match(smoke, /deployed content catalog still makes individual blocking pack requests/);
});
